#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RulesCallSeatsItem {
    pub id: MemberId,
    pub name: String,
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub team: Option<String>,
    pub bot: bool,
}

/// One call into a managed game's rules. `fn` names the rule; the other fields are its arguments.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RulesCall {
    #[serde(rename = "fn")]
    pub fn_: RulesCallFn,
    /// init: the seated players, in party order.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub seats: Option<Vec<RulesCallSeatsItem>>,
    /// init: the game's options (manifest `opts`). May carry ArrayBuffers (see Json).
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub opts: Option<serde_json::Map<String, serde_json::Value>>,
    /// init: a random seed.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub seed: Option<i64>,
    /// init: which match of this run (0, then 1 on the first rematch…).
    #[serde(rename = "match", skip_serializing_if = "Option::is_none", default)]
    pub match_: Option<i64>,
    /// apply: the move. May carry ArrayBuffers (see Json).
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub action: Option<Json>,
    /// apply: who made it (a bot's id for a bot).
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub by: Option<MemberId>,
    /// tick: each seat's latest input. May carry ArrayBuffers (see Json).
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub inputs: Option<BTreeMap<String, Json>>,
    /// tick: seconds since the last tick (1 / manifest tick).
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub dt: Option<f64>,
    /// view (null: a spectator), bot, skip, leave: the seat.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub seat: Option<MemberId>,
    /// restore: what `snapshot()` returned on the old host. May carry ArrayBuffers (see Json).
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub snapshot: Option<Json>,
}

/// One call's outcome: `v`, what the rule returned (apply: null or true when allowed, else the
/// reason as a string; skip / leave: true if the game acted on it; both optional), or `err` when it
/// threw or does not exist.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RulesOut {
    /// May carry ArrayBuffers (see Json).
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub v: Option<Json>,
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub err: Option<String>,
}

/// `rules`, shell to frame. Request, Layer 2: call a managed game's rules, in order, in one round
/// trip. Reply `{ out: [rulesOut…] }`, one per call. Only the host's rules are live; every phone's
/// frame answers on a takeover.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Rules {
    pub v: V2,
    pub id: Id,
    /// At least 1 items.
    pub calls: Vec<RulesCall>,
}

/// `view`, shell to frame. Layer 2: what this phone's player may see now (the rules' `view({ seat
/// })`), in `state`. Sent only when it changed.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct View {
    pub v: V2,
    /// May carry ArrayBuffers (see Json).
    pub state: Json,
}

/// `rejected`, shell to frame. Layer 2: the host's rules refused this player's `act`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Rejected {
    pub v: V2,
    /// May carry ArrayBuffers (see Json).
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub a: Option<Json>,
    pub reason: String,
}

/// `runtime.file`, frame to shell. Request: a file of a runtime the platform ships, for a game
/// whose language needs one (manifest `runtime: "python"`: Pyodide, from sdk/v1/pyodide/). Reply `{
/// bytes, type }`. Only that folder; it does not count toward the game's size cap.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RuntimeFile {
    pub v: V2,
    pub id: Id,
    /// Relative to the runtime's folder, e.g. `pyodide.asm.wasm`. At most 256 chars.
    pub path: String,
}

/// `http`, frame to shell. Request, a web app (manifest `app`, sdk/v2/web-shim.js): one request to
/// the app's server, which runs on the host's phone. The reply always has ok: true and an HTTP
/// answer `{ status, headers, body }` (body base64; a failure is a 5xx).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Http {
    pub v: V2,
    pub id: Id,
    /// At most 16 chars.
    pub method: String,
    /// At most 2048 chars.
    pub path: String,
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub query: Option<String>,
    /// Each: Exactly 2 items.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub headers: Option<Vec<Vec<String>>>,
    /// base64, at most 1 MB decoded
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub body: Option<String>,
}

/// `address`, frame to shell. A web app's address changed (pushState, or a navigation with
/// `reload`): the party's address, so every phone follows.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Address {
    pub v: V2,
    /// Starts with /. At most 2048 chars.
    pub url: String,
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub reload: Option<bool>,
}

/// Frame to shell.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[allow(clippy::large_enum_variant)]
#[serde(tag = "t")]
pub enum ToShell {
    #[serde(rename = "hello")]
    Hello(Hello),
    #[serde(rename = "ready")]
    Ready(Ready),
    #[serde(rename = "reply")]
    Reply(Reply),
    #[serde(rename = "listen")]
    Listen(Listen),
    #[serde(rename = "send")]
    Send(SendMessage),
    #[serde(rename = "emitAs")]
    EmitAs(EmitAs),
    #[serde(rename = "meta")]
    Meta(Meta),
    #[serde(rename = "store.set")]
    StoreSet(StoreSet),
    #[serde(rename = "session.set")]
    SessionSet(SessionSet),
    #[serde(rename = "asset")]
    Asset(Asset),
    #[serde(rename = "result")]
    Result(ResultMessage),
    #[serde(rename = "end")]
    End(End),
    #[serde(rename = "hostNew")]
    HostNew(HostNew),
    #[serde(rename = "toast")]
    Toast(Toast),
    #[serde(rename = "ask")]
    Ask(Ask),
    #[serde(rename = "haptic")]
    Haptic(Haptic),
    #[serde(rename = "timer.open")]
    TimerOpen(TimerOpen),
    #[serde(rename = "timer.do")]
    TimerDo(TimerDo),
    #[serde(rename = "wait.turn")]
    WaitTurn(WaitTurn),
    #[serde(rename = "wait.pause")]
    WaitPause(WaitPause),
    #[serde(rename = "seal.listen")]
    SealListen(SealListen),
    #[serde(rename = "seal.send")]
    SealSend(SealSend),
    #[serde(rename = "commit")]
    Commit(Commit),
    #[serde(rename = "verify")]
    Verify(Verify),
    #[serde(rename = "act")]
    Act(Act),
    #[serde(rename = "input")]
    Input(Input),
    #[serde(rename = "runtime.file")]
    RuntimeFile(RuntimeFile),
    #[serde(rename = "http")]
    Http(Http),
    #[serde(rename = "address")]
    Address(Address),
    /// A `t` this version does not know. The protocol says to ignore it (the other side may be
    /// newer); it cannot be serialised.
    #[serde(other, skip_serializing)]
    Unknown,
}

/// Shell to frame.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[allow(clippy::large_enum_variant)]
#[serde(tag = "t")]
pub enum ToFrame {
    #[serde(rename = "init")]
    Init(Init),
    #[serde(rename = "roster")]
    Roster(Roster),
    #[serde(rename = "join")]
    Join(Join),
    #[serde(rename = "leave")]
    Leave(Leave),
    #[serde(rename = "msg")]
    Msg(Msg),
    #[serde(rename = "theme.set")]
    ThemeSet(ThemeSet),
    #[serde(rename = "takeOver")]
    TakeOver(TakeOver),
    #[serde(rename = "unmount")]
    Unmount(Unmount),
    #[serde(rename = "reply")]
    Reply(Reply),
    #[serde(rename = "timer")]
    Timer(Timer),
    #[serde(rename = "wait")]
    Wait(Wait),
    #[serde(rename = "paused")]
    Paused(Paused),
    #[serde(rename = "sealed")]
    Sealed(Sealed),
    #[serde(rename = "rules")]
    Rules(Rules),
    #[serde(rename = "view")]
    View(View),
    #[serde(rename = "rejected")]
    Rejected(Rejected),
    /// A `t` this version does not know. The protocol says to ignore it (the other side may be
    /// newer); it cannot be serialised.
    #[serde(other, skip_serializing)]
    Unknown,
}

